	AddPoliticalReasonCoreTag(tags, parts, "封地利益", "封地", "要塞", "城镇", "城堡", "连片治理");
	AddPoliticalReasonCoreTag(tags, parts, "政策取向", "政策权重", "王权", "贵族寡头", "平民");
	AddPoliticalReasonCoreTag(tags, parts, "盟约义务", "盟友", "结盟", "召战", "应召");
