private static int ResolvePartyTransferRecruitMaxTier(int trustLevelIndex)
{
	if (trustLevelIndex <= 4)
	{
		return 0;
	}
	if (trustLevelIndex == 5)
	{
		return 1;
	}
	if (trustLevelIndex == 6)
	{
		return 2;
	}
	if (trustLevelIndex == 7)
	{
		return 3;
	}
	if (trustLevelIndex == 8)
	{
		return 4;
	}
	return int.MaxValue;
}

