private static int ClampWildernessNonHeroPartyTransferAmount(PartyTransferPromptEntry entry, int requestedAmount, PartyBase wildernessNonHeroSource, CharacterObject representativeCharacter)
{
	int amount = Math.Max(0, requestedAmount);
	if (wildernessNonHeroSource == null)
	{
		return amount;
	}
	if (entry == null || entry.OwnerParty != wildernessNonHeroSource)
	{
		return 0;
	}
	if (!IsSamePartyTransferCharacter(entry.Character, representativeCharacter))
	{
		return amount;
	}
	try
	{
		TroopRoster roster = wildernessNonHeroSource.MemberRoster;
		int index = roster?.FindIndexOfTroop(entry.Character) ?? (-1);
		if (index < 0)
		{
			return 0;
		}
		int currentCount = Math.Max(0, roster.GetElementCopyAtIndex(index).Number);
		return Math.Min(amount, Math.Max(0, currentCount - 1));
	}
	catch
	{
		return 0;
	}
}

private static int TransferPartyMemberEntry(PartyTransferPromptEntry entry, int requestedAmount, PartyBase targetParty)
{
	if (IsPartyTransferVolunteerEntry(entry))
	{
		return TransferPartyVolunteerEntry(entry, requestedAmount, targetParty);
	}
	if (entry == null || targetParty == null || entry.OwnerParty == null || entry.OwnerParty == targetParty || entry.Character == null || entry.Character.IsHero || entry.Character == CharacterObject.PlayerCharacter)
	{
		return 0;
	}
	TroopRoster memberRoster = entry.OwnerParty.MemberRoster;
	TroopRoster memberRoster2 = targetParty.MemberRoster;
	if (memberRoster == null || memberRoster2 == null)
	{
		return 0;
	}
	int num = memberRoster.FindIndexOfTroop(entry.Character);
	if (num < 0)
	{
		return 0;
	}
	TroopRosterElement elementCopyAtIndex = memberRoster.GetElementCopyAtIndex(num);
	int num2 = Math.Min(Math.Max(0, requestedAmount), Math.Max(0, elementCopyAtIndex.Number));
	if (num2 <= 0)
	{
		return 0;
	}
	int num3 = 0;
	if (elementCopyAtIndex.Number > 0 && elementCopyAtIndex.WoundedNumber > 0)
	{
		num3 = (num2 >= elementCopyAtIndex.Number) ? elementCopyAtIndex.WoundedNumber : Math.Min(num2, Math.Max(0, (int)Math.Round((double)elementCopyAtIndex.WoundedNumber * (double)num2 / (double)elementCopyAtIndex.Number, MidpointRounding.AwayFromZero)));
	}
	int num4 = 0;
	if (elementCopyAtIndex.Number > 0 && elementCopyAtIndex.Xp > 0)
	{
		num4 = (num2 >= elementCopyAtIndex.Number) ? elementCopyAtIndex.Xp : Math.Max(0, (int)Math.Round((double)elementCopyAtIndex.Xp * (double)num2 / (double)elementCopyAtIndex.Number, MidpointRounding.AwayFromZero));
	}
	memberRoster.AddToCounts(entry.Character, -num2, insertAtFront: false, -num3, 0, false, -1);
	if (num4 > 0)
	{
		memberRoster.AddXpToTroop(entry.Character, -num4);
	}
	memberRoster2.AddToCounts(entry.Character, num2, insertAtFront: false, num3, 0, false, -1);
	if (num4 > 0)
	{
		memberRoster2.AddXpToTroop(entry.Character, num4);
	}
	return num2;
}

private static int TransferPartyVolunteerEntry(PartyTransferPromptEntry entry, int requestedAmount, PartyBase targetParty)
{
	if (!IsPartyTransferVolunteerEntry(entry) || targetParty?.MemberRoster == null || requestedAmount <= 0)
	{
		return 0;
	}
	Hero volunteerOwner = entry.VolunteerOwner;
	CharacterObject character = entry.Character;
	CharacterObject[] volunteerTypes = volunteerOwner.VolunteerTypes;
	if (volunteerTypes == null)
	{
		return 0;
	}
	int maximumRecruitableVolunteerIndex = GetMaximumRecruitableVolunteerIndex(volunteerOwner);
	if (maximumRecruitableVolunteerIndex < 0)
	{
		return 0;
	}
	int num = 0;
	int num2 = Math.Min(Math.Min(5, maximumRecruitableVolunteerIndex), volunteerTypes.Length - 1);
	for (int i = 0; i <= num2 && num < requestedAmount; i++)
	{
		if (volunteerTypes[i] != character)
		{
			continue;
		}
		volunteerTypes[i] = null;
		targetParty.MemberRoster.AddToCounts(character, 1, insertAtFront: false, 0, 0, true, -1);
		num++;
	}
	if (num > 0)
	{
		CampaignEventDispatcher.Instance.OnUnitRecruited(character, num);
	}
	return num;
}

private static bool IsPartyTransferDungeonSourceValid(PartyTransferPromptEntry entry, Clan expectedOwnerClan)
{
	if (entry?.SourceSettlement == null)
	{
		return true;
	}
	Settlement sourceSettlement = entry.SourceSettlement;
	if (expectedOwnerClan == null || sourceSettlement.OwnerClan != expectedOwnerClan || !sourceSettlement.IsFortification)
	{
		return false;
	}
	if (entry.OwnerParty == sourceSettlement.Party)
	{
		return true;
	}
	try
	{
		return sourceSettlement.Parties.Any((MobileParty x) => x != null && x.IsGarrison && x.Party == entry.OwnerParty);
	}
	catch
	{
		return false;
	}
}

private static int TransferPartyPrisonerEntry(PartyTransferPromptEntry entry, int requestedAmount, PartyBase targetParty, Clan expectedDungeonOwnerClan = null)
{
	if (entry == null || targetParty == null || entry.OwnerParty == null || entry.OwnerParty == targetParty || entry.Character == null)
	{
		return 0;
	}
	if (entry.Character.IsHero)
	{
		Hero heroObject = entry.Character.HeroObject;
		TroopRoster sourceRoster = entry.OwnerParty.PrisonRoster;
		if (requestedAmount <= 0 || heroObject == null || !heroObject.IsPrisoner || heroObject.PartyBelongedToAsPrisoner != entry.OwnerParty || sourceRoster == null || sourceRoster.FindIndexOfTroop(entry.Character) < 0 || !IsPartyTransferDungeonSourceValid(entry, expectedDungeonOwnerClan))
		{
			return 0;
		}
		if (targetParty.PrisonRoster?.FindIndexOfTroop(entry.Character) >= 0)
		{
			return 0;
		}
		try
		{
			TransferPrisonerAction.Apply(entry.Character, entry.OwnerParty, targetParty);
			return heroObject.PartyBelongedToAsPrisoner == targetParty && (targetParty.PrisonRoster?.FindIndexOfTroop(entry.Character) ?? (-1)) >= 0 ? 1 : 0;
		}
		catch
		{
			return 0;
		}
	}
	TroopRoster prisonRoster = entry.OwnerParty.PrisonRoster;
	if (prisonRoster == null)
	{
		return 0;
	}
	int num = prisonRoster.FindIndexOfTroop(entry.Character);
	if (num < 0)
	{
		return 0;
	}
	TroopRosterElement elementCopyAtIndex = prisonRoster.GetElementCopyAtIndex(num);
	int num2 = Math.Min(Math.Max(0, requestedAmount), Math.Max(0, elementCopyAtIndex.Number));
	if (num2 <= 0)
	{
		return 0;
	}
	int num3 = 0;
	if (elementCopyAtIndex.Number > 0 && elementCopyAtIndex.Xp > 0)
	{
		num3 = (num2 >= elementCopyAtIndex.Number) ? elementCopyAtIndex.Xp : Math.Max(0, (int)Math.Round((double)elementCopyAtIndex.Xp * (double)num2 / (double)elementCopyAtIndex.Number, MidpointRounding.AwayFromZero));
	}
	prisonRoster.AddToCounts(entry.Character, -num2, insertAtFront: false, 0, 0, false, -1);
	if (num3 > 0)
	{
		prisonRoster.AddXpToTroop(entry.Character, -num3);
	}
	targetParty.AddPrisoner(entry.Character, num2);
	if (num3 > 0)
	{
		targetParty.PrisonRoster?.AddXpToTroop(entry.Character, num3);
	}
	return num2;
}

private static void AppendPartyTransferFactItem(StringBuilder builder, PartyTransferPromptEntry entry, int amount)
{
	if (builder == null || entry == null || amount <= 0)
	{
		return;
	}
	if (builder.Length > 0)
	{
		builder.Append('、');
	}
	builder.Append(entry.DisplayName).Append('x').Append(amount);
}

private static string StripPartyTransferTags(string text)
{
	string result = Regex.Replace(text ?? "", "\\[ATT:[^\\]\\r\\n]*\\]", "", RegexOptions.IgnoreCase);
	return Regex.Replace(result, "\\[ATP:[^\\]\\r\\n]*\\]", "", RegexOptions.IgnoreCase).Trim();
}

public static bool TryApplyPartyTransferTagsForExternal(Hero targetHero, CharacterObject targetCharacter, int targetAgentIndex, ref string content, out List<string> generatedFacts, out List<string> notifications)
{
	generatedFacts = new List<string>();
	notifications = new List<string>();
	List<string> factResults = generatedFacts;
	List<string> notificationResults = notifications;
	try
	{
		string text = content ?? "";
		Hero ruleHero = ResolvePartyTransferRuleHero(targetHero, targetCharacter);
		bool wildernessNonHeroEligible = TryResolveWildernessNonHeroPartyTransferSource(targetHero, targetCharacter, targetAgentIndex, out PartyBase wildernessNonHeroSource);
		if (!IsPartyTransferLordEligible(targetHero, targetCharacter) && !IsPartyTransferNotableRecruitEligible(ruleHero) && !wildernessNonHeroEligible)
		{
			content = StripPartyTransferTags(text);
			return false;
		}
		MatchCollection matchCollection = TransferTroopTagRegex.Matches(text);
		MatchCollection matchCollection2 = TransferPrisonerTagRegex.Matches(text);
		if ((matchCollection?.Count ?? 0) <= 0 && (matchCollection2?.Count ?? 0) <= 0)
		{
			content = StripPartyTransferTags(text);
			return false;
		}
		bool hasTroopSnapshot = PromptListRetrievalService.TryGetPartyTransferSnapshot(PromptListRetrievalService.PartyTransferTroopsSnapshotScope, targetHero, targetCharacter, targetAgentIndex, out var list2);
		bool hasPrisonerSnapshot = PromptListRetrievalService.TryGetPartyTransferSnapshot(PromptListRetrievalService.PartyTransferPrisonersSnapshotScope, targetHero, targetCharacter, targetAgentIndex, out var list3);
		bool hasAllTroopSnapshot = PromptListRetrievalService.TryGetPartyTransferSnapshot(PromptListRetrievalService.PartyTransferAllTroopsSnapshotScope, targetHero, targetCharacter, targetAgentIndex, out var allTroops);
		bool hasAllPrisonerSnapshot = PromptListRetrievalService.TryGetPartyTransferSnapshot(PromptListRetrievalService.PartyTransferAllPrisonersSnapshotScope, targetHero, targetCharacter, targetAgentIndex, out var allPrisoners);
		PartyBase party = Hero.MainHero?.PartyBelongedTo?.Party ?? MobileParty.MainParty?.Party;
		string text2 = ResolvePartyTransferTargetDisplayName(targetHero, targetCharacter, targetAgentIndex);
		bool flag = false;
		int attemptedEntries = 0;
		int successfulEntries = 0;
		int failedOrPartialEntries = 0;
		long actualUnits = 0L;
		long actualValue = 0L;
		if (party != null)
		{
			StringBuilder transferredTroopFacts = new StringBuilder();
			StringBuilder recruitedVolunteerFacts = new StringBuilder();
			StringBuilder transferredPrisonerFacts = new StringBuilder();
			void applyTroop(PartyTransferPromptEntry entry, int requested, string source)
			{
				attemptedEntries++;
				int authorizedRequested = ClampWildernessNonHeroPartyTransferAmount(entry, requested, wildernessNonHeroSource, targetCharacter);
				int applied = TransferPartyMemberEntry(entry, authorizedRequested, party);
				Logger.Log("Logic", "[PartyTransfer] ATT source=" + source + " amount=" + requested + " resolved=" + (entry?.DisplayName ?? "null") + " section=" + (entry?.Section.ToString() ?? "null") + " applied=" + applied);
				if (applied <= 0)
				{
					failedOrPartialEntries++;
					return;
				}
				flag = true;
				successfulEntries++;
				if (applied < Math.Max(0, requested))
				{
					failedOrPartialEntries++;
				}
				actualUnits = TransferQuantitySpec.AddValue(actualUnits, applied);
				actualValue = TransferQuantitySpec.AddProduct(actualValue, applied, Math.Max(1, entry?.HirePriceDenarsPerUnit ?? 0));
				bool isVolunteer = IsPartyTransferVolunteerEntry(entry);
				AppendPartyTransferFactItem(isVolunteer ? recruitedVolunteerFacts : transferredTroopFacts, entry, applied);
				notificationResults.Add((isVolunteer ? "已招募 " : "已获得 ") + applied + " 名" + entry.DisplayName);
			}
			void applyPrisoner(PartyTransferPromptEntry entry, int requested, string source)
			{
				attemptedEntries++;
				bool currentWildernessSource = wildernessNonHeroSource == null || entry?.OwnerParty == wildernessNonHeroSource;
				int applied = currentWildernessSource ? TransferPartyPrisonerEntry(entry, requested, party, ruleHero?.Clan) : 0;
				Logger.Log("Logic", "[PartyTransfer] ATP source=" + source + " amount=" + requested + " resolved=" + (entry?.DisplayName ?? "null") + " applied=" + applied);
				if (applied <= 0)
				{
					failedOrPartialEntries++;
					return;
				}
				flag = true;
				successfulEntries++;
				if (applied < Math.Max(0, requested))
				{
					failedOrPartialEntries++;
				}
				actualUnits = TransferQuantitySpec.AddValue(actualUnits, applied);
				actualValue = TransferQuantitySpec.AddProduct(actualValue, applied, Math.Max(1, entry?.BuyPriceDenarsPerUnit ?? 0));
				AppendPartyTransferFactItem(transferredPrisonerFacts, entry, applied);
				notificationResults.Add("已获得 " + (entry.IsHero ? ("俘虏" + entry.DisplayName) : (applied + " 名" + entry.DisplayName + "俘虏")));
			}
			bool troopAll = matchCollection.Cast<Match>().Any((Match x) => x.Success && (TransferQuantitySpec.IsAllValue(x.Groups[2].Value) || (TransferQuantitySpec.IsAllValue(x.Groups[1].Value) && int.TryParse(x.Groups[2].Value, out var amount) && amount > 0)));
			if (troopAll)
			{
				if (!hasAllTroopSnapshot)
				{
					attemptedEntries++;
					failedOrPartialEntries++;
					Logger.Log("Logic", "[PartyTransfer] ATT ALL rejected: authorization snapshot missing.");
				}
				foreach (PartyTransferPromptEntry entry in hasAllTroopSnapshot ? allTroops : new List<PartyTransferPromptEntry>())
				{
					applyTroop(entry, Math.Max(0, entry?.Count ?? 0), "ALL");
				}
			}
			else
			{
				if (!hasTroopSnapshot)
				{
					attemptedEntries += matchCollection?.Count ?? 0;
					failedOrPartialEntries += matchCollection?.Count ?? 0;
					Logger.Log("Logic", "[PartyTransfer] ATT rejected: authorization snapshot missing.");
				}
				foreach (Match item in hasTroopSnapshot ? matchCollection.Cast<Match>() : Enumerable.Empty<Match>())
				{
					if (item.Success && int.TryParse(item.Groups[1].Value, out var index) && int.TryParse(item.Groups[2].Value, out var amount))
					{
						applyTroop(FindDisplayIndexedPartyTransferEntry(list2, index), amount, "index=" + index);
					}
				}
			}
			bool prisonerAll = matchCollection2.Cast<Match>().Any((Match x) => x.Success && (TransferQuantitySpec.IsAllValue(x.Groups[2].Value) || (TransferQuantitySpec.IsAllValue(x.Groups[1].Value) && int.TryParse(x.Groups[2].Value, out var amount) && amount > 0)));
			if (prisonerAll)
			{
				if (!hasAllPrisonerSnapshot)
				{
					attemptedEntries++;
					failedOrPartialEntries++;
					Logger.Log("Logic", "[PartyTransfer] ATP ALL rejected: authorization snapshot missing.");
				}
				foreach (PartyTransferPromptEntry entry in hasAllPrisonerSnapshot ? allPrisoners : new List<PartyTransferPromptEntry>())
				{
					applyPrisoner(entry, Math.Max(0, entry?.Count ?? 0), "ALL");
				}
			}
			else
			{
				if (!hasPrisonerSnapshot)
				{
					attemptedEntries += matchCollection2?.Count ?? 0;
					failedOrPartialEntries += matchCollection2?.Count ?? 0;
					Logger.Log("Logic", "[PartyTransfer] ATP rejected: authorization snapshot missing.");
				}
				foreach (Match item in hasPrisonerSnapshot ? matchCollection2.Cast<Match>() : Enumerable.Empty<Match>())
				{
					if (item.Success && int.TryParse(item.Groups[1].Value, out var index) && int.TryParse(item.Groups[2].Value, out var amount))
					{
						applyPrisoner(FindDisplayIndexedPartyTransferEntry(list3, index), amount, "index=" + index);
					}
				}
			}
			string batchSummary = "部队与俘虏转移汇总：尝试项" + attemptedEntries + "，成功项" + successfulEntries + "，失败或不足项" + failedOrPartialEntries + "，实际转移" + actualUnits + "人，实际指导总值约" + actualValue + "第纳尔。";
			StringBuilder combinedFact = new StringBuilder(256);
			combinedFact.Append("[AFEF NPC行为补充] ").Append(text2).Append("已完成一次部队与俘虏转移。");
			if (transferredTroopFacts.Length > 0)
			{
				combinedFact.Append("转入玩家麾下：").Append(transferredTroopFacts).Append('。');
			}
			if (recruitedVolunteerFacts.Length > 0)
			{
				combinedFact.Append("允许玩家从原版待招募士兵中招募：").Append(recruitedVolunteerFacts).Append('。');
			}
			if (transferredPrisonerFacts.Length > 0)
			{
				combinedFact.Append("交给玩家的俘虏：").Append(transferredPrisonerFacts).Append('。');
			}
			combinedFact.Append(batchSummary);
			factResults.Add(combinedFact.ToString());
			notificationResults.Add(batchSummary);
			Logger.Log("Logic", "[PartyTransfer] batch_done troopAll=" + troopAll + " prisonerAll=" + prisonerAll + " attempted=" + attemptedEntries + " succeeded=" + successfulEntries + " failedOrPartial=" + failedOrPartialEntries + " actualUnits=" + actualUnits + " actualValue=" + actualValue);
		}
		text = StripPartyTransferTags(text);
		content = text;
		return flag;
	}
	catch
	{
		content = StripPartyTransferTags(content);
		return false;
	}
}

public static int TransferPlayerPartyEntryToCounterpartyForExternal(Hero targetHero, CharacterObject targetCharacter, int targetAgentIndex, PartyTransferPromptEntry entry, int amount)
{
