		{
			DailyMemoryDraft dailyMemoryDraft = (drafts ?? Enumerable.Empty<DailyMemoryDraft>()).OrderByDescending((DailyMemoryDraft x) => x.GameDayIndex).FirstOrDefault((DailyMemoryDraft x) => x?.Lines != null && x.Lines.Count > 0);
