		}
		string text = (line.Text ?? "").Trim();
		string name = (npcName ?? "").Trim();
		if (!string.IsNullOrWhiteSpace(name) && (text.Contains("对" + name + "说") || text.Contains("对" + name + "喊") || text.Contains("向" + name + "说") || text.Contains("向" + name + "喊")))
