private static string GetVoiceGroupShortName(string key)
{
	return (key ?? "").ToLowerInvariant() switch
	{
		"male_young" => "青男", 
		"male_middle" => "中男", 
		"male_old" => "老男", 
		"female_young" => "青女", 
		"female_middle" => "中女", 
		"female_old" => "老女", 
		_ => key ?? "", 
	};
}

