		{
			return;
		}
		_presentationRoundTask = groupTask;
		_presentationRoundEpoch = Volatile.Read(ref _sceneConversationEpoch);
		_presentationRoundFinishedAt = -1f;
		_presentationRoundPendingSince = -1f;
