		float now = GetApplicationTimeSafe();
		if (task == null)
		{
			if (_presentationRoundPendingSince < 0f)
			{
				return false;
			}
			if (now - _presentationRoundPendingSince < PresentationRoundStartTimeoutSeconds)
			{
				return true;
			}
			_presentationRoundPendingSince = -1f;
			return false;
