			return;
		}
		list = new List<int>(_speakingAgentIndices);
	}
	Mission mission = Mission.Current;
	var agents = mission?.Agents;
	if (agents == null)
	{
		return;
	}
	foreach (int agentIndex in list)
	{
		try
		{
			Agent agent = agents.FirstOrDefault((Agent a) => a != null && a.Index == agentIndex);
