						LlmRetryPrompt.ShowFailurePopup("AnimusForge 前处理失败", ex.Message);
					}
					catch
					{
					}
				});
			}
		}
	}
	return receipt == null ? Task.Run(RunGroupAsync) : RunSceneGroupOnMainThreadAsync(RunGroupAsync);
}

